import { emailShell, deliveryBadge, inr } from './base';
import type { DeliveryType } from '../types';

interface ShippingEmailOptions {
  customerName: string;
  orderRef: string;
  deliveryType: DeliveryType;
  trackingNumber?: string;
  carrier?: string;
  estimatedDelivery?: string;
  farmerNotes?: string;
  trackUrl: string;
}

export function shippingEmail(opts: ShippingEmailOptions): { subject: string; html: string } {
  const isPickup = opts.deliveryType === 'pickup';

  const html = emailShell(`
    <div class="card">
      <div class="card-header">
        <p style="margin:0 0 8px;">${deliveryBadge(opts.deliveryType)}</p>
        <h1>${isPickup ? '🏪 Ready for Pickup!' : '🚚 Your Order is On Its Way!'}</h1>
        <p>
          ${isPickup
            ? `Hi ${escHtml(opts.customerName)}, your fresh produce is <strong style="color:#34d399;">ready for collection</strong> at the farmer's location.`
            : `Hi ${escHtml(opts.customerName)}, your Kissan Connect order has been dispatched and is heading your way!`
          }
        </p>
      </div>
      <div class="card-body">
        <p style="color:#9d93f0;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;margin:0 0 4px;">
          Order Reference
        </p>
        <p style="font-family:'Courier New',monospace;font-size:18px;font-weight:900;color:#f0eeff;margin:0 0 20px;">
          ${escHtml(opts.orderRef)}
        </p>

        ${!isPickup && (opts.trackingNumber || opts.carrier || opts.estimatedDelivery) ? `
        <div class="info-grid">
          ${opts.trackingNumber ? `
          <div class="info-row">
            <span class="info-label">📦 Tracking</span>
            <span class="info-val" style="font-family:'Courier New',monospace;">${escHtml(opts.trackingNumber)}</span>
          </div>` : ''}
          ${opts.carrier ? `
          <div class="info-row">
            <span class="info-label">🚛 Carrier</span>
            <span class="info-val">${escHtml(opts.carrier)}</span>
          </div>` : ''}
          ${opts.estimatedDelivery ? `
          <div class="info-row">
            <span class="info-label">📅 Est. Delivery</span>
            <span class="info-val" style="color:#34d399;">${escHtml(opts.estimatedDelivery)}</span>
          </div>` : ''}
        </div>` : ''}

        ${isPickup ? `
        <div style="background:#0a1a10;border:1px solid rgba(52,211,153,.2);border-radius:12px;padding:20px;text-align:center;margin:16px 0;">
          <p style="margin:0;font-size:14px;color:#6ee7b7;">
            ✅ Bring your <strong>Order Reference ${escHtml(opts.orderRef)}</strong> when you collect your order.
          </p>
        </div>` : ''}

        ${opts.farmerNotes ? `
        <div style="background:#0f0f1a;border:1px solid #2a2740;border-left:3px solid #7c6fe9;border-radius:8px;padding:14px 16px;margin:16px 0;">
          <p style="margin:0 0 4px;font-size:12px;font-weight:700;text-transform:uppercase;color:#7c6fe9;">🌾 Farmer Delivery Notes</p>
          <p style="margin:0;font-size:14px;color:#b8b4d4;">${escHtml(opts.farmerNotes)}</p>
        </div>` : ''}

        <div style="text-align:center;margin:20px 0 4px;">
          <a href="${opts.trackUrl}" class="btn">📦 Track Order Live</a>
        </div>
      </div>
      <div class="card-footer">
        <p style="margin:0;font-size:13px;color:#5a5778;">
          Questions? Reply to this email or contact <a href="mailto:support@kissanconnect.in">support@kissanconnect.in</a>
        </p>
      </div>
    </div>`,
    isPickup
      ? `Your order ${opts.orderRef} is ready for pickup!`
      : `Your order ${opts.orderRef} has been shipped!`
  );

  return {
    subject: isPickup
      ? `🏪 Order ${opts.orderRef} Ready for Pickup — Kissan Connect`
      : `🚚 Order ${opts.orderRef} Shipped — ${opts.estimatedDelivery ? `Arriving ${opts.estimatedDelivery}` : 'On its way!'}`,
    html,
  };
}

function escHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
