import type { D1Database } from '@cloudflare/workers-types';
import { getProductById } from '../db/queries';

export interface CartEntry {
  productId: number;
  quantity: number;
}

export interface ValidatedItem {
  productId: number;
  productName: string;
  productSku: string;
  farmerId: string;
  farmerName: string;
  quantity: number;
  unit: string;
  unitPrice: number;
  costPrice: number;
  lineTotal: number;
}

export type InventoryValidationResult =
  | { ok: true; items: ValidatedItem[]; subtotal: number }
  | { ok: false; errors: string[] };

/**
 * Validate all cart items against live DB stock.
 * Returns validated items with pricing snapshot, or an errors array.
 */
export async function validateInventory(
  db: D1Database,
  cartItems: CartEntry[]
): Promise<InventoryValidationResult> {
  if (!cartItems.length) return { ok: false, errors: ['Cart is empty'] };

  const errors: string[] = [];
  const validatedItems: ValidatedItem[] = [];
  let subtotal = 0;

  for (const entry of cartItems) {
    if (!Number.isInteger(entry.productId) || entry.productId <= 0) {
      errors.push(`Invalid product ID: ${entry.productId}`);
      continue;
    }
    if (entry.quantity <= 0) {
      errors.push(`Quantity must be > 0 for product ${entry.productId}`);
      continue;
    }

    const product = await getProductById(db, entry.productId);

    if (!product) {
      errors.push(`Product #${entry.productId} not found`);
      continue;
    }
    if (!product.active) {
      errors.push(`"${product.name}" is currently unavailable`);
      continue;
    }
    if (entry.quantity < product.min_qty) {
      errors.push(`Minimum order for "${product.name}" is ${product.min_qty} ${product.unit}`);
      continue;
    }
    if (product.max_daily_qty !== null && entry.quantity > product.max_daily_qty) {
      errors.push(`Maximum ${product.max_daily_qty} ${product.unit} per order for "${product.name}"`);
      continue;
    }
    if (product.stock_qty < entry.quantity) {
      errors.push(
        `Insufficient stock for "${product.name}" — only ${product.stock_qty} ${product.unit} available`
      );
      continue;
    }

    const lineTotal = product.price * entry.quantity;
    subtotal += lineTotal;

    validatedItems.push({
      productId: product.id,
      productName: product.name,
      productSku: product.sku,
      farmerId: product.farmer_id,
      farmerName: product.farmer_name,
      quantity: entry.quantity,
      unit: product.unit,
      unitPrice: product.price,
      costPrice: product.cost_price,
      lineTotal,
    });
  }

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, items: validatedItems, subtotal };
}

/** Check if a product has sufficient stock for a given quantity. */
export async function hasStock(
  db: D1Database,
  productId: number,
  quantity: number
): Promise<boolean> {
  const product = await getProductById(db, productId);
  return !!product && product.active === 1 && product.stock_qty >= quantity;
}
