import type { RazorpayPaymentLink, RazorpayWebhookPayload } from '../types';
import { toBase64, hmacSHA256, timingSafeEqual } from '../utils/crypto';

const RAZORPAY_BASE = 'https://api.razorpay.com/v1';
const PAYMENT_LINK_EXPIRY_SECS = 3600; // 1 hour

interface CreatePaymentLinkOptions {
  orderRef: string;
  amount: number;           // in INR (will be converted to paise)
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  description: string;
  callbackUrl: string;
}

/**
 * Create a Razorpay Payment Link via the Payment Links API.
 * Returns the link object with short_url for emailing.
 */
export async function createPaymentLink(
  keyId: string,
  keySecret: string,
  opts: CreatePaymentLinkOptions
): Promise<RazorpayPaymentLink> {
  const auth = toBase64(`${keyId}:${keySecret}`);
  const expireBy = Math.floor(Date.now() / 1000) + PAYMENT_LINK_EXPIRY_SECS;

  const body = {
    amount: Math.round(opts.amount * 100), // paise
    currency: 'INR',
    accept_partial: false,
    description: opts.description,
    reference_id: opts.orderRef,
    customer: {
      name: opts.customerName,
      email: opts.customerEmail,
      contact: opts.customerPhone.replace(/\D/g, '').replace(/^0/, '+91'),
    },
    notify: {
      sms: true,
      email: true,
    },
    reminder_enable: false,
    expire_by: expireBy,
    callback_url: opts.callbackUrl,
    callback_method: 'get',
    notes: {
      order_ref: opts.orderRef,
      platform: 'Kissan Connect',
    },
  };

  const res = await fetch(`${RAZORPAY_BASE}/payment_links`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${auth}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  });

  if (!res.ok) {
    const errBody = await res.text();
    throw new Error(`Razorpay API error ${res.status}: ${errBody}`);
  }

  return res.json<RazorpayPaymentLink>();
}

/**
 * Verify Razorpay webhook signature.
 * Signature = HMAC-SHA256(rawBody, webhookSecret)
 */
export async function verifyWebhookSignature(
  rawBody: string,
  signature: string,
  webhookSecret: string
): Promise<boolean> {
  const expected = await hmacSHA256(webhookSecret, rawBody);
  return timingSafeEqual(expected, signature);
}

/**
 * Cancel a payment link (e.g., on order rejection).
 */
export async function cancelPaymentLink(
  keyId: string,
  keySecret: string,
  linkId: string
): Promise<void> {
  const auth = toBase64(`${keyId}:${keySecret}`);
  await fetch(`${RAZORPAY_BASE}/payment_links/${linkId}/cancel`, {
    method: 'POST',
    headers: { Authorization: `Basic ${auth}` },
  });
}
