/** Standard JSON success response */
export function ok<T>(data: T, status = 200): Response {
  return Response.json({ success: true, data }, { status });
}

/** Standard JSON error response */
export function err(message: string, status = 400, details?: unknown): Response {
  return Response.json(
    { success: false, error: message, ...(details ? { details } : {}) },
    { status }
  );
}

/** 401 Unauthorized */
export function unauthorized(msg = 'Unauthorized'): Response {
  return err(msg, 401);
}

/** 403 Forbidden */
export function forbidden(msg = 'Forbidden'): Response {
  return err(msg, 403);
}

/** 404 Not Found */
export function notFound(msg = 'Not found'): Response {
  return err(msg, 404);
}

/** 429 Too Many Requests */
export function tooManyRequests(retryAfter?: number): Response {
  const headers: Record<string, string> = {};
  if (retryAfter) headers['Retry-After'] = String(retryAfter);
  return new Response(
    JSON.stringify({ success: false, error: 'Too many requests. Please slow down.' }),
    { status: 429, headers: { 'Content-Type': 'application/json', ...headers } }
  );
}

/** 500 Internal Server Error */
export function serverError(msg = 'Internal server error'): Response {
  return err(msg, 500);
}
