import { Hono } from 'hono';
import type { Env } from '../types';
import { getOrderByRef, getOrderItems } from '../db/queries';
import { ok, notFound } from '../utils/response';

const track = new Hono<{ Bindings: Env }>();

// ─── GET /api/track/:ref ─────────────────────────────────────────
track.get('/:ref', async (c) => {
  const ref = c.req.param('ref').trim().toUpperCase();
  const order = await getOrderByRef(c.env.DB, ref);
  if (!order) return notFound('Order not found');

  const items = await getOrderItems(c.env.DB, order.id);

  // Only expose safe fields to public
  return ok({
    orderRef: order.order_ref,
    status: order.status,
    deliveryType: order.delivery_type,
    customer: {
      name: order.customer_name,
      email: maskEmail(order.customer_email),
      phone: maskPhone(order.customer_phone),
    },
    subtotal: order.subtotal,
    deliveryCharge: order.delivery_charge,
    total: order.total,
    // Payment info (only show URL, not internal IDs)
    paymentUrl: order.status === 'accepted' ? (order.payment_link_url ?? undefined) : undefined,
    // Shipping info (only show when shipped/delivered)
    shippingInfo: (order.status === 'shipped' || order.status === 'delivered')
      ? {
          trackingNumber: order.tracking_number,
          carrier: order.carrier,
          estimatedDelivery: order.estimated_delivery,
        }
      : null,
    // Timeline timestamps
    timeline: {
      placed: order.created_at,
      verified: order.status !== 'pending' ? order.updated_at : null,
      paid: order.paid_at,
      shipped: order.shipped_at,
      delivered: order.delivered_at,
    },
    farmerNotes: order.farmer_notes,
    rejectionReason: order.status === 'rejected' ? order.rejection_reason : null,
    items: items.map((i) => ({
      name: i.product_name,
      emoji: itemEmoji(i.product_sku),
      quantity: i.quantity,
      unit: i.unit,
      unitPrice: i.unit_price,
      lineTotal: i.line_total,
      farmerName: i.farmer_name,
    })),
    createdAt: order.created_at,
  });
});

/** Mask email: show first 2 chars and domain only */
function maskEmail(email: string): string {
  const [local, domain] = email.split('@');
  if (!local || !domain) return email;
  const visible = local.slice(0, 2);
  return `${visible}***@${domain}`;
}

/** Mask phone: show last 4 digits */
function maskPhone(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  return `****${digits.slice(-4)}`;
}

/** Map SKU prefix to emoji (falls back to 🌿) */
function itemEmoji(sku: string): string {
  const map: Record<string, string> = {
    'VEG-TOM': '🍅', 'VEG-ONI': '🧅', 'VEG-SPI': '🥬', 'VEG-POT': '🥔', 'VEG-CAR': '🥕',
    'FRT-MNG': '🥭', 'FRT-BAN': '🍌', 'FRT-GUA': '🍐', 'FRT-LIM': '🍋',
    'DAI-MLK': '🥛', 'DAI-GHE': '🧈', 'DAI-PAN': '🧀', 'DAI-CRD': '🥣',
    'GRN-WHT': '🌾', 'GRN-RIC': '🍚',
    'OIL-MUS': '🫙', 'OIL-COC': '🥥',
    'HSH-JAG': '🍯', 'HSH-SUG': '🧂',
  };
  const prefix = sku.slice(0, 7);
  return map[prefix] ?? '🌿';
}

export default track;
