import type { D1Database } from '@cloudflare/workers-types';
import type { Product, Order, OrderItem, DailySummary } from '../types';

// ─── Products ────────────────────────────────────────────────────

export async function getProducts(
  db: D1Database,
  opts: { category?: string; search?: string; activeOnly?: boolean } = {}
): Promise<Product[]> {
  let sql = 'SELECT * FROM products WHERE 1=1';
  const params: (string | number)[] = [];

  if (opts.activeOnly !== false) {
    sql += ' AND active = 1';
  }
  if (opts.category) {
    sql += ' AND category = ?';
    params.push(opts.category);
  }
  if (opts.search) {
    sql += ' AND (name LIKE ? OR name_hi LIKE ? OR description LIKE ? OR farmer_name LIKE ?)';
    const q = `%${opts.search}%`;
    params.push(q, q, q, q);
  }
  sql += ' ORDER BY is_featured DESC, rating DESC, name ASC';

  const stmt = db.prepare(sql);
  const res = await (params.length ? stmt.bind(...params) : stmt).all<Product>();
  return res.results;
}

export async function getProductById(db: D1Database, id: number): Promise<Product | null> {
  return db.prepare('SELECT * FROM products WHERE id = ?').bind(id).first<Product>();
}

export async function getProductBySku(db: D1Database, sku: string): Promise<Product | null> {
  return db.prepare('SELECT * FROM products WHERE sku = ?').bind(sku).first<Product>();
}

export async function getRelatedProducts(db: D1Database, productId: number, category: string): Promise<Product[]> {
  const res = await db
    .prepare('SELECT * FROM products WHERE category = ? AND id != ? AND active = 1 ORDER BY is_featured DESC LIMIT 6')
    .bind(category, productId)
    .all<Product>();
  return res.results;
}

export async function createProduct(db: D1Database, p: Omit<Product, 'id' | 'created_at' | 'updated_at'>): Promise<number> {
  const result = await db.prepare(`
    INSERT INTO products (
      name, name_hi, sku, category, emoji, description, description_hi,
      price, cost_price, unit, stock_qty, min_qty, max_daily_qty,
      farmer_id, farmer_name, farmer_location, farmer_phone, farmer_email,
      is_organic, is_featured, active, rating, review_count
    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
    RETURNING id
  `).bind(
    p.name, p.name_hi, p.sku, p.category, p.emoji, p.description, p.description_hi,
    p.price, p.cost_price, p.unit, p.stock_qty, p.min_qty, p.max_daily_qty,
    p.farmer_id, p.farmer_name, p.farmer_location, p.farmer_phone, p.farmer_email,
    p.is_organic, p.is_featured, p.active, p.rating, p.review_count
  ).first<{ id: number }>();
  return result!.id;
}

export async function updateProduct(db: D1Database, id: number, fields: Partial<Product>): Promise<boolean> {
  const allowed = [
    'name','name_hi','price','cost_price','stock_qty','min_qty','max_daily_qty',
    'description','description_hi','emoji','is_organic','is_featured','active',
    'farmer_name','farmer_location','farmer_phone','farmer_email',
  ] as const;

  const setClauses: string[] = [];
  const params: unknown[] = [];

  for (const key of allowed) {
    if (key in fields) {
      setClauses.push(`${key} = ?`);
      params.push(fields[key]);
    }
  }
  if (setClauses.length === 0) return false;

  setClauses.push("updated_at = datetime('now')");
  params.push(id);

  await db.prepare(`UPDATE products SET ${setClauses.join(', ')} WHERE id = ?`)
    .bind(...params)
    .run();
  return true;
}

export async function decrementStock(db: D1Database, productId: number, quantity: number): Promise<void> {
  await db.prepare(`
    UPDATE products SET stock_qty = MAX(0, stock_qty - ?), updated_at = datetime('now')
    WHERE id = ?
  `).bind(quantity, productId).run();
}

export async function incrementStock(db: D1Database, productId: number, quantity: number): Promise<void> {
  await db.prepare(`
    UPDATE products SET stock_qty = stock_qty + ?, updated_at = datetime('now')
    WHERE id = ?
  `).bind(quantity, productId).run();
}

// ─── Orders ──────────────────────────────────────────────────────

export async function createOrder(
  db: D1Database,
  order: Omit<Order, 'id' | 'created_at' | 'updated_at'>,
  items: Omit<OrderItem, 'id' | 'order_id'>[]
): Promise<number> {
  const result = await db.prepare(`
    INSERT INTO orders (
      order_ref, customer_name, customer_email, customer_phone, customer_address, notes,
      delivery_type, status, subtotal, delivery_charge, total
    ) VALUES (?,?,?,?,?,?,?,?,?,?,?) RETURNING id
  `).bind(
    order.order_ref, order.customer_name, order.customer_email,
    order.customer_phone, order.customer_address, order.notes,
    order.delivery_type, 'pending', order.subtotal, order.delivery_charge, order.total
  ).first<{ id: number }>();

  const orderId = result!.id;

  // Insert items in batch
  for (const item of items) {
    await db.prepare(`
      INSERT INTO order_items
        (order_id, product_id, product_name, product_sku, farmer_id, farmer_name,
         quantity, unit, unit_price, cost_price, line_total)
      VALUES (?,?,?,?,?,?,?,?,?,?,?)
    `).bind(
      orderId, item.product_id, item.product_name, item.product_sku,
      item.farmer_id, item.farmer_name, item.quantity, item.unit,
      item.unit_price, item.cost_price, item.line_total
    ).run();
  }

  return orderId;
}

export async function getOrderByRef(db: D1Database, ref: string): Promise<Order | null> {
  return db.prepare('SELECT * FROM orders WHERE order_ref = ?').bind(ref).first<Order>();
}

export async function getOrderItems(db: D1Database, orderId: number): Promise<OrderItem[]> {
  const res = await db
    .prepare('SELECT * FROM order_items WHERE order_id = ? ORDER BY id')
    .bind(orderId)
    .all<OrderItem>();
  return res.results;
}

export async function updateOrderStatus(
  db: D1Database,
  ref: string,
  status: string,
  extra: Record<string, unknown> = {}
): Promise<void> {
  const setClauses = ["status = ?", "updated_at = datetime('now')"];
  const params: unknown[] = [status];

  for (const [k, v] of Object.entries(extra)) {
    setClauses.push(`${k} = ?`);
    params.push(v);
  }
  params.push(ref);

  await db.prepare(`UPDATE orders SET ${setClauses.join(', ')} WHERE order_ref = ?`)
    .bind(...params)
    .run();
}

