export async function listOrders(
  db: D1Database,
  opts: { status?: string; limit?: number; offset?: number; farmerId?: string } = {}
): Promise<Order[]> {
  let sql = 'SELECT DISTINCT o.* FROM orders o';
  const params: (string | number)[] = [];

  if (opts.farmerId) {
    sql += ' JOIN order_items oi ON oi.order_id = o.id AND oi.farmer_id = ?';
    params.push(opts.farmerId);
  }

  sql += ' WHERE 1=1';

  if (opts.status) {
    sql += ' AND o.status = ?';
    params.push(opts.status);
  }

  sql += ' ORDER BY o.created_at DESC';
  sql += ` LIMIT ${opts.limit ?? 50} OFFSET ${opts.offset ?? 0}`;

  const res = await db.prepare(sql).bind(...params).all<Order>();
  return res.results;
}

// ─── Daily Summaries ─────────────────────────────────────────────

export async function upsertDailySummary(
  db: D1Database,
  date: string,
  data: Partial<DailySummary>
): Promise<void> {
  const setClauses: string[] = ["updated_at = datetime('now')"];
  const params: unknown[] = [];

  const fields: (keyof DailySummary)[] = [
    'total_orders','completed_orders','cancelled_orders','total_revenue',
    'total_farmer_payout','total_items_sold','top_products_json',
    'low_stock_alerts_json','category_breakdown_json','ai_insights',
  ];

  for (const f of fields) {
    if (f in data) {
      setClauses.push(`${f} = ?`);
      params.push(data[f]);
    }
  }

  params.push(date);

  await db.prepare(`
    INSERT INTO daily_summaries (summary_date) VALUES (?)
    ON CONFLICT(summary_date) DO NOTHING
  `).bind(date).run();

  if (setClauses.length > 1) {
    await db.prepare(
      `UPDATE daily_summaries SET ${setClauses.join(', ')} WHERE summary_date = ?`
    ).bind(...params).run();
  }
}

export async function getDailySummary(db: D1Database, date: string): Promise<DailySummary | null> {
  return db.prepare('SELECT * FROM daily_summaries WHERE summary_date = ?').bind(date).first<DailySummary>();
}
