import { Hono } from 'hono';
import type { Env, PlaceOrderPayload } from '../types';
import { validateInventory } from '../services/inventory';
import { createOTP } from '../services/otp';
import { sendEmail } from '../services/resend';
import { otpEmail } from '../emails/otp';
import {
  createOrder, decrementStock, getOrderByRef, getOrderItems,
} from '../db/queries';
import { generateOrderRef } from '../utils/orderRef';
import { ok, err, notFound } from '../utils/response';

const DELIVERY_CHARGE = 40;

const orders = new Hono<{ Bindings: Env }>();

// ─── POST /api/order ─────────────────────────────────────────────
orders.post('/order', async (c) => {
  let body: PlaceOrderPayload;
  try {
    body = await c.req.json<PlaceOrderPayload>();
  } catch {
    return err('Invalid JSON body');
  }

  // ── Validate customer fields ──
  const { customer, items, deliveryType } = body;
  if (!customer?.name?.trim())  return err('customer.name is required');
  if (!customer?.email?.trim()) return err('customer.email is required');
  if (!customer?.phone?.trim()) return err('customer.phone is required');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customer.email)) return err('Invalid email address');
  if (!/^[\d+\s\-]{8,15}$/.test(customer.phone)) return err('Invalid phone number');
  if (!Array.isArray(items) || items.length === 0) return err('Order must have at least one item');
  if (deliveryType !== 'delivery' && deliveryType !== 'pickup') return err('deliveryType must be "delivery" or "pickup"');
  if (deliveryType === 'delivery' && !customer.address?.trim()) return err('Delivery address is required for home delivery');

  // ── Validate inventory ──
  const inv = await validateInventory(c.env.DB, items.map((i) => ({ productId: i.productId, quantity: i.quantity })));
  if (!inv.ok) return err('Inventory validation failed', 422, inv.errors);

  const deliveryCharge = deliveryType === 'delivery' ? DELIVERY_CHARGE : 0;
  const total = inv.subtotal + deliveryCharge;

  // ── Create order in D1 ──
  const orderRef = generateOrderRef();
  const orderId = await createOrder(
    c.env.DB,
    {
      order_ref: orderRef,
      customer_name: customer.name.trim(),
      customer_email: customer.email.trim().toLowerCase(),
      customer_phone: customer.phone.trim(),
      customer_address: customer.address?.trim() ?? null,
      notes: customer.notes?.trim() ?? null,
      delivery_type: deliveryType,
      status: 'pending',
      subtotal: inv.subtotal,
      delivery_charge: deliveryCharge,
      total,
      otp_attempts: 0,
      otp_resends: 0,
      payment_link_id: null,
      payment_link_url: null,
      payment_link_expires_at: null,
      razorpay_payment_id: null,
      razorpay_order_id: null,
      paid_at: null,
      tracking_number: null,
      carrier: null,
      shipped_at: null,
      estimated_delivery: null,
      delivered_at: null,
      rejection_reason: null,
      farmer_notes: null,
      accepted_by: null,
    },
    inv.items.map((i) => ({
      product_id: i.productId,
      product_name: i.productName,
      product_sku: i.productSku,
      farmer_id: i.farmerId,
      farmer_name: i.farmerName,
      quantity: i.quantity,
      unit: i.unit,
      unit_price: i.unitPrice,
      cost_price: i.costPrice,
      line_total: i.lineTotal,
    }))
  );

  // ── Decrement stock ──
  for (const item of inv.items) {
    await decrementStock(c.env.DB, item.productId, item.quantity);
  }

  // ── Generate OTP and store in KV ──
  const otp = await createOTP(c.env.STORE_KV, orderRef, customer.email.trim().toLowerCase());

  // ── Send OTP email ──
  try {
    const { subject, html } = otpEmail({
      customerName: customer.name.trim(),
      orderRef,
      otp,
      deliveryType,
    });
    await sendEmail(c.env.RESEND_API_KEY, c.env.EMAIL_FROM, {
      to: customer.email.trim().toLowerCase(),
      subject,
      html,
      tags: [{ name: 'type', value: 'otp' }, { name: 'order_ref', value: orderRef }],
    });
  } catch (e) {
    console.error('[OTP Email Error]', e);
    // Don't fail the order — OTP is still in KV
  }

  return ok(
    {
      orderRef,
      message: 'Order placed! Check your email for the verification OTP.',
      itemCount: inv.items.length,
      total,
    },
    201
  );
});

export default orders;
