/**
 * HMAC-SHA256 using the Web Crypto API (native in Cloudflare Workers).
 * Returns a hex-encoded digest string.
 */
export async function hmacSHA256(secret: string, message: string): Promise<string> {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    enc.encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, enc.encode(message));
  return [...new Uint8Array(sig)]
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

/**
 * Timing-safe string comparison to prevent timing attacks on HMAC verification.
 */
export function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);
  let diff = 0;
  for (let i = 0; i < aBytes.length; i++) {
    diff |= (aBytes[i] ?? 0) ^ (bBytes[i] ?? 0);
  }
  return diff === 0;
}

/**
 * Encode a string to Base64 (for Razorpay Basic auth).
 */
export function toBase64(str: string): string {
  return btoa(str);
}

/** Generate a 6-digit numeric OTP */
export function generateOTP(): string {
  const arr = crypto.getRandomValues(new Uint32Array(1));
  return String((arr[0]! % 900000) + 100000);
}
