import type { Context, Next } from 'hono';
import type { Env, RateLimitData } from '../types';
import { tooManyRequests } from '../utils/response';

interface RateConfig {
  limit: number;       // max requests
  windowSecs: number;  // window in seconds
}

// Route-specific limits
const ROUTE_CONFIGS: Record<string, RateConfig> = {
  'POST /api/order':               { limit: 10,  windowSecs: 60 },
  'POST /api/order/verify':        { limit: 10,  windowSecs: 60 },
  'POST /api/order/resend-otp':    { limit: 5,   windowSecs: 60 },
  'GET /api/catalog':              { limit: 120, windowSecs: 60 },
  'GET /api/catalog/:id':          { limit: 120, windowSecs: 60 },
  'GET /api/track/:ref':           { limit: 30,  windowSecs: 60 },
  'DEFAULT':                       { limit: 60,  windowSecs: 60 },
};

function getRouteKey(method: string, path: string): string {
  // Normalize dynamic segments
  const normalized = path
    .replace(/\/api\/catalog\/\d+/, '/api/catalog/:id')
    .replace(/\/api\/track\/[\w-]+/, '/api/track/:ref');
  const key = `${method} ${normalized}`;
  return ROUTE_CONFIGS[key] ? key : 'DEFAULT';
}

export async function rateLimitMiddleware(
  c: Context<{ Bindings: Env }>,
  next: Next
): Promise<Response | void> {
  const ip =
    c.req.header('CF-Connecting-IP') ??
    c.req.header('X-Forwarded-For')?.split(',')[0]?.trim() ??
    'unknown';

  const routeKey = getRouteKey(c.req.method, c.req.path);
  const config = ROUTE_CONFIGS[routeKey] ?? ROUTE_CONFIGS['DEFAULT']!;
  const kvKey = `rl:${routeKey.replace(/\s+/g, ':')}:${ip}`;

  const now = Date.now();
  const windowMs = config.windowSecs * 1000;

  // Fetch current window data
  const raw = await c.env.STORE_KV.get(kvKey);
  let data: RateLimitData = raw
    ? (JSON.parse(raw) as RateLimitData)
    : { count: 0, windowStart: now };

  // Reset window if expired
  if (now - data.windowStart >= windowMs) {
    data = { count: 0, windowStart: now };
  }

  data.count += 1;

  // Persist updated counter (TTL = window seconds + 5s grace)
  await c.env.STORE_KV.put(kvKey, JSON.stringify(data), {
    expirationTtl: config.windowSecs + 5,
  });

  // Set rate-limit response headers
  const remaining = Math.max(0, config.limit - data.count);
  const resetAt = Math.ceil((data.windowStart + windowMs) / 1000);
  c.header('X-RateLimit-Limit', String(config.limit));
  c.header('X-RateLimit-Remaining', String(remaining));
  c.header('X-RateLimit-Reset', String(resetAt));

  if (data.count > config.limit) {
    const retryAfter = Math.ceil((data.windowStart + windowMs - now) / 1000);
    return tooManyRequests(retryAfter);
  }

  return next();
}
