import { Hono } from 'hono';
import type { Env, CreateProductPayload } from '../types';
import { requireAdmin } from '../middleware/auth';
import {
  getProducts, getProductById, getRelatedProducts,
  createProduct, updateProduct, getProductBySku,
} from '../db/queries';
import { ok, err, notFound } from '../utils/response';

const catalog = new Hono<{ Bindings: Env }>();

// ─── GET /api/catalog ────────────────────────────────────────────
catalog.get('/', async (c) => {
  const category = c.req.query('category');
  const search   = c.req.query('search');
  const featured = c.req.query('featured') === 'true';

  const products = await getProducts(c.env.DB, {
    category,
    search,
    activeOnly: true,
  });

  const result = featured ? products.filter((p) => p.is_featured === 1) : products;

  return ok(
    result.map((p) => ({
      id: p.id,
      name: p.name,
      nameHi: p.name_hi,
      sku: p.sku,
      category: p.category,
      emoji: p.emoji,
      description: p.description,
      descriptionHi: p.description_hi,
      price: p.price,
      unit: p.unit,
      stockQty: p.stock_qty,
      minQty: p.min_qty,
      farmerName: p.farmer_name,
      farmerLocation: p.farmer_location,
      isOrganic: p.is_organic === 1,
      isFeatured: p.is_featured === 1,
      rating: p.rating,
      reviewCount: p.review_count,
    }))
  );
});

// ─── GET /api/catalog/:id ────────────────────────────────────────
catalog.get('/:id', async (c) => {
  const id = parseInt(c.req.param('id')!, 10);
  if (isNaN(id)) return err('Invalid product ID');

  const product = await getProductById(c.env.DB, id);
  if (!product || !product.active) return notFound('Product not found');

  const related = await getRelatedProducts(c.env.DB, id, product.category);

  return ok({
    product: {
      id: product.id,
      name: product.name,
      nameHi: product.name_hi,
      sku: product.sku,
      category: product.category,
      emoji: product.emoji,
      description: product.description,
      descriptionHi: product.description_hi,
      price: product.price,
      unit: product.unit,
      stockQty: product.stock_qty,
      minQty: product.min_qty,
      maxDailyQty: product.max_daily_qty,
      farmerName: product.farmer_name,
      farmerLocation: product.farmer_location,
      farmerPhone: product.farmer_phone,
      isOrganic: product.is_organic === 1,
      isFeatured: product.is_featured === 1,
      rating: product.rating,
      reviewCount: product.review_count,
    },
    related: related.map((p) => ({
      id: p.id, name: p.name, nameHi: p.name_hi, category: p.category,
      emoji: p.emoji, price: p.price, unit: p.unit,
      stockQty: p.stock_qty, isOrganic: p.is_organic === 1,
      rating: p.rating, reviewCount: p.review_count,
      farmerName: p.farmer_name, farmerLocation: p.farmer_location,
    })),
  });
});

// ─── POST /api/catalog (admin only) ─────────────────────────────
catalog.post('/', requireAdmin, async (c) => {
  const body = await c.req.json<CreateProductPayload>().catch(() => null);
  if (!body) return err('Invalid JSON body');

  if (!body.name || !body.sku || !body.category || !body.price || !body.costPrice || !body.farmerId || !body.farmerName) {
    return err('Missing required fields: name, sku, category, price, costPrice, farmerId, farmerName');
  }

  const existing = await getProductBySku(c.env.DB, body.sku);
  if (existing) return err(`SKU "${body.sku}" already exists`, 409);

  const id = await createProduct(c.env.DB, {
    name: body.name,
    name_hi: body.nameHi ?? '',
    sku: body.sku.toUpperCase(),
    category: body.category,
    emoji: body.emoji ?? '🌿',
    description: body.description ?? '',
    description_hi: body.descriptionHi ?? '',
    price: body.price,
    cost_price: body.costPrice,
    unit: body.unit ?? 'kg',
    stock_qty: body.stockQty ?? 0,
    min_qty: body.minQty ?? 0.5,
    max_daily_qty: body.maxDailyQty ?? null,
    farmer_id: body.farmerId,
    farmer_name: body.farmerName,
    farmer_location: body.farmerLocation ?? null,
    farmer_phone: body.farmerPhone ?? null,
    farmer_email: body.farmerEmail ?? null,
    is_organic: body.isOrganic ? 1 : 0,
    is_featured: body.isFeatured ? 1 : 0,
    active: 1,
    rating: 4.5,
    review_count: 0,
  });

  return ok({ id, message: 'Product created' }, 201);
});

// ─── PUT /api/catalog/:id (admin only) ──────────────────────────
catalog.put('/:id', requireAdmin, async (c) => {
  const id = parseInt(c.req.param('id')!, 10);
  if (isNaN(id)) return err('Invalid product ID');

  const body = await c.req.json<Partial<CreateProductPayload>>().catch(() => null);
  if (!body || typeof body !== 'object') return err('Invalid JSON body');

  const product = await getProductById(c.env.DB, id);
  if (!product) return notFound('Product not found');

  await updateProduct(c.env.DB, id, {
    name: body.name ?? undefined,
    name_hi: body.nameHi ?? undefined,
    price: body.price ?? undefined,
    cost_price: body.costPrice ?? undefined,
    stock_qty: body.stockQty ?? undefined,
    min_qty: body.minQty ?? undefined,
    max_daily_qty: body.maxDailyQty ?? undefined,
    description: body.description ?? undefined,
    description_hi: body.descriptionHi ?? undefined,
    emoji: body.emoji ?? undefined,
    is_organic: body.isOrganic !== undefined ? (body.isOrganic ? 1 : 0) : undefined,
    is_featured: body.isFeatured !== undefined ? (body.isFeatured ? 1 : 0) : undefined,
    farmer_name: body.farmerName ?? undefined,
    farmer_location: body.farmerLocation ?? undefined,
    farmer_phone: body.farmerPhone ?? undefined,
    farmer_email: body.farmerEmail ?? undefined,
  } as any);

  return ok({ message: 'Product updated' });
});

// ─── DELETE /api/catalog/:id (admin — soft delete) ───────────────
catalog.delete('/:id', requireAdmin, async (c) => {
  const id = parseInt(c.req.param('id')!, 10);
  if (isNaN(id)) return err('Invalid product ID');

  const product = await getProductById(c.env.DB, id);
  if (!product) return notFound('Product not found');

  await updateProduct(c.env.DB, id, { active: 0 } as any);
  return ok({ message: 'Product deactivated' });
});

// ─── PATCH /api/catalog/:id/stock (admin — bulk stock update) ────
catalog.patch('/:id/stock', requireAdmin, async (c) => {
  const id = parseInt(c.req.param('id')!, 10);
  if (isNaN(id)) return err('Invalid product ID');

  const { qty } = await c.req.json<{ qty: number }>().catch(() => ({ qty: NaN }));
  if (isNaN(qty) || qty < 0) return err('qty must be a non-negative number');

  const product = await getProductById(c.env.DB, id);
  if (!product) return notFound('Product not found');

  await updateProduct(c.env.DB, id, { stock_qty: qty } as any);
  return ok({ message: 'Stock updated', newStock: qty });
});

export default catalog;
