import type { KVNamespace } from '@cloudflare/workers-types';
import type { OTPData } from '../types';
import { generateOTP } from '../utils/crypto';

const OTP_TTL_SECS = 600;          // 10 minutes
const MAX_ATTEMPTS = 5;
const MAX_RESENDS = 3;
const RESEND_COOLDOWN_SECS = 60;

export type OTPVerifyResult =
  | { success: true }
  | { success: false; reason: 'invalid' | 'max_attempts' | 'expired' };

export type OTPResendResult =
  | { success: true; otp: string }
  | { success: false; reason: 'cooldown' | 'max_resends' | 'not_found'; retryAfter?: number };

function kvKey(orderRef: string): string {
  return `otp:${orderRef}`;
}

/** Create and store a fresh OTP for an order. Returns the OTP string. */
export async function createOTP(
  kv: KVNamespace,
  orderRef: string,
  customerEmail: string
): Promise<string> {
  const otp = generateOTP();
  const data: OTPData = {
    otp,
    orderRef,
    customerEmail,
    attempts: 0,
    resends: 0,
    lastResendAt: null,
    createdAt: Date.now(),
  };
  await kv.put(kvKey(orderRef), JSON.stringify(data), { expirationTtl: OTP_TTL_SECS });
  return otp;
}

/** Verify an OTP. Updates attempt count and deletes on success. */
export async function verifyOTP(
  kv: KVNamespace,
  orderRef: string,
  inputOtp: string
): Promise<OTPVerifyResult> {
  const raw = await kv.get(kvKey(orderRef));
  if (!raw) return { success: false, reason: 'expired' };

  const data = JSON.parse(raw) as OTPData;

  if (data.attempts >= MAX_ATTEMPTS) {
    return { success: false, reason: 'max_attempts' };
  }

  if (data.otp !== inputOtp.trim()) {
    data.attempts += 1;
    // Keep remaining TTL by re-writing with same TTL
    const remainingTtl = Math.max(
      1,
      OTP_TTL_SECS - Math.floor((Date.now() - data.createdAt) / 1000)
    );
    await kv.put(kvKey(orderRef), JSON.stringify(data), { expirationTtl: remainingTtl });
    return { success: false, reason: 'invalid' };
  }

  // Success — delete OTP from KV
  await kv.delete(kvKey(orderRef));
  return { success: true };
}

/** Resend OTP with cooldown and max-resend enforcement. Returns new OTP if allowed. */
export async function resendOTP(
  kv: KVNamespace,
  orderRef: string,
  customerEmail: string
): Promise<OTPResendResult> {
  const raw = await kv.get(kvKey(orderRef));
  if (!raw) return { success: false, reason: 'not_found' };

  const data = JSON.parse(raw) as OTPData;

  if (data.resends >= MAX_RESENDS) {
    return { success: false, reason: 'max_resends' };
  }

  if (data.lastResendAt !== null) {
    const elapsed = Math.floor((Date.now() - data.lastResendAt) / 1000);
    if (elapsed < RESEND_COOLDOWN_SECS) {
      return {
        success: false,
        reason: 'cooldown',
        retryAfter: RESEND_COOLDOWN_SECS - elapsed,
      };
    }
  }

  // Generate new OTP
  const newOtp = generateOTP();
  const updatedData: OTPData = {
    ...data,
    otp: newOtp,
    attempts: 0,                 // reset attempts on resend
    resends: data.resends + 1,
    lastResendAt: Date.now(),
    createdAt: Date.now(),       // fresh TTL start
  };

  await kv.put(kvKey(orderRef), JSON.stringify(updatedData), { expirationTtl: OTP_TTL_SECS });
  return { success: true, otp: newOtp };
}

/** Delete OTP record (used on order cancellation). */
export async function deleteOTP(kv: KVNamespace, orderRef: string): Promise<void> {
  await kv.delete(kvKey(orderRef));
}
