import type { Context, Next } from 'hono';
import type { Env, AuthContext } from '../types';
import { unauthorized, forbidden } from '../utils/response';

type HonoCtx = Context<{ Bindings: Env; Variables: { auth: AuthContext } }>;

/**
 * Admin-only middleware — requires X-API-Key header matching ADMIN_API_KEY.
 * Attaches { isAdmin: true } to c.var.auth.
 */
export async function requireAdmin(c: HonoCtx, next: Next): Promise<Response | void> {
  const apiKey = c.req.header('X-API-Key') ?? c.req.header('Authorization')?.replace('Bearer ', '');
  if (!apiKey || apiKey !== c.env.ADMIN_API_KEY) {
    return unauthorized('Admin API key required');
  }
  c.set('auth', { isAdmin: true, isFarmer: false, farmerId: null, adminEmail: 'admin', sessionId: null });
  return next();
}

/**
 * Farmer middleware — accepts either:
 *   1. X-API-Key = ADMIN_API_KEY (admins can act as farmers)
 *   2. X-Session-ID = active KV session belonging to a farmer
 */
export async function requireAuth(c: HonoCtx, next: Next): Promise<Response | void> {
  // Check admin API key first
  const apiKey = c.req.header('X-API-Key');
  if (apiKey && apiKey === c.env.ADMIN_API_KEY) {
    c.set('auth', { isAdmin: true, isFarmer: true, farmerId: null, adminEmail: 'admin', sessionId: null });
    return next();
  }

  // Check session
  const sessionId = c.req.header('X-Session-ID');
  if (!sessionId) return unauthorized('Authentication required');

  const raw = await c.env.STORE_KV.get(`session:${sessionId}`);
  if (!raw) return unauthorized('Session expired or invalid');

  const session = JSON.parse(raw) as { adminEmail: string; role: string; farmerId: string | null; expiresAt: number };
  if (Date.now() > session.expiresAt) {
    await c.env.STORE_KV.delete(`session:${sessionId}`);
    return unauthorized('Session expired');
  }

  c.set('auth', {
    isAdmin: session.role === 'admin',
    isFarmer: session.role === 'farmer',
    farmerId: session.farmerId,
    adminEmail: session.adminEmail,
    sessionId,
  });
  return next();
}

/**
 * Middleware: require admin OR authenticated farmer.
 * Farmers can only see/act on their own orders.
 */
export async function requireAdminOrFarmer(c: HonoCtx, next: Next): Promise<Response | void> {
  return requireAuth(c, next);
}
