import { Hono } from 'hono';
import type { Env } from '../types';
import { getOrderByRef, updateOrderStatus, getOrderItems } from '../db/queries';
import { verifyWebhookSignature } from '../services/razorpay';
import { sendEmail } from '../services/resend';
import { ok, err, forbidden, serverError } from '../utils/response';

const payments = new Hono<{ Bindings: Env }>();

// ─── POST /api/webhooks/razorpay ─────────────────────────────────
// Razorpay sends: payment_link.paid event
payments.post('/webhooks/razorpay', async (c) => {
  const rawBody = await c.req.text();
  const signature = c.req.header('X-Razorpay-Signature') ?? '';

  // ── Verify HMAC signature ──
  const isValid = await verifyWebhookSignature(
    rawBody,
    signature,
    c.env.RAZORPAY_WEBHOOK_SECRET
  );
  if (!isValid) return forbidden('Invalid webhook signature');

  let payload: any;
  try { payload = JSON.parse(rawBody); }
  catch { return err('Invalid JSON payload'); }

  const event: string = payload.event ?? '';
  console.log('[Razorpay Webhook]', event);

  // ── Handle payment_link.paid ──
  if (event === 'payment_link.paid') {
    const linkEntity = payload?.payload?.payment_link?.entity;
    const paymentEntity = payload?.payload?.payment?.entity;

    if (!linkEntity) {
      console.error('[Webhook] Missing payment_link entity');
      return ok({ received: true });
    }

    const orderRef: string = linkEntity.reference_id ?? '';
    const razorpayPaymentId: string = paymentEntity?.id ?? '';

    if (!orderRef) {
      console.error('[Webhook] No reference_id in payment link entity');
      return ok({ received: true });
    }

    const order = await getOrderByRef(c.env.DB, orderRef);
    if (!order) {
      console.error('[Webhook] Order not found:', orderRef);
      return ok({ received: true }); // acknowledge anyway
    }

    if (order.status === 'paid' || order.status === 'shipped' || order.status === 'delivered') {
      // Already processed — idempotent
      return ok({ received: true, message: 'Already processed' });
    }

    // ── Update order to paid ──
    await updateOrderStatus(c.env.DB, orderRef, 'paid', {
      razorpay_payment_id: razorpayPaymentId || null,
      paid_at: new Date().toISOString(),
    });

    // ── Send payment confirmation email ──
    try {
      const items = await getOrderItems(c.env.DB, order.id);
      await sendEmail(c.env.RESEND_API_KEY, c.env.EMAIL_FROM, {
        to: order.customer_email,
        subject: `✅ Payment Confirmed — Order ${orderRef} | Kissan Connect`,
        html: buildPaymentConfirmedHtml(order.customer_name, orderRef, order.total, order.delivery_type),
        tags: [{ name: 'type', value: 'payment_confirmed' }],
      });
    } catch (e) {
      console.error('[Payment Email Error]', e);
    }

    return ok({ received: true, orderRef, status: 'paid' });
  }

  // Handle other events gracefully
  return ok({ received: true, event });
});

function buildPaymentConfirmedHtml(
  name: string,
  orderRef: string,
  total: number,
  deliveryType: 'delivery' | 'pickup'
): string {
  const escaped = name.replace(/</g, '&lt;');
  const badge = deliveryType === 'delivery'
    ? '<span class="badge badge-purple">🚚 Home Delivery</span>'
    : '<span class="badge badge-green">🏪 Self Pickup — FREE</span>';
  const amountStr = `₹${total.toLocaleString('en-IN')}`;
  return `<!DOCTYPE html><html><body style="background:#0a0a10;font-family:sans-serif;color:#e8e6f5;"><div style="max-width:520px;margin:0 auto;padding:24px;"><div style="background:#13131f;border:1px solid #1e1e30;border-radius:16px;overflow:hidden;"><div style="background:linear-gradient(135deg,rgba(124,111,233,.15),rgba(52,211,153,.08));padding:28px;border-bottom:1px solid #1e1e30;">${badge}<h1 style="margin:12px 0 8px;font-size:22px;color:#f0eeff;">💚 Payment Confirmed!</h1><p style="margin:0;color:#b8b4d4;">Hi ${escaped}, your payment of <strong style="color:#34d399;">${amountStr}</strong> for order <strong style="color:#9d93f0;">${orderRef}</strong> has been received. The farmer will now prepare your order.</p></div></div></div></body></html>`;
}

export default payments;
