/** Generate a unique order reference: ORD-XXXXXXXX */
export function generateOrderRef(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let result = 'ORD-';
  const array = crypto.getRandomValues(new Uint8Array(8));
  for (const byte of array) {
    result += chars[byte % chars.length];
  }
  return result;
}

/** Generate a purchase order reference: PO-XXXXXXXX */
export function generatePORef(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let result = 'PO-';
  const array = crypto.getRandomValues(new Uint8Array(8));
  for (const byte of array) {
    result += chars[byte % chars.length];
  }
  return result;
}

/** Generate a session ID (32 random hex chars) */
export function generateSessionId(): string {
  const array = crypto.getRandomValues(new Uint8Array(16));
  return [...array].map((b) => b.toString(16).padStart(2, '0')).join('');
}
