import { Hono } from 'hono';
import type { Env, AuthContext } from './types';
import { rateLimitMiddleware } from './middleware/rateLimit';

// ── Route modules ──────────────────────────────────────────────────
import catalogRouter   from './routes/catalog';
import ordersRouter    from './routes/orders';
import otpRouter       from './routes/otp';
import paymentsRouter  from './routes/payments';
import adminRouter     from './routes/admin';
import trackRouter     from './routes/track';
import summariesRouter from './routes/summaries';

// ─────────────────────────────────────────────────────────────────
type Variables = { auth: AuthContext };
const app = new Hono<{ Bindings: Env; Variables: Variables }>();

// ── CORS ──────────────────────────────────────────────────────────
app.use('*', async (c, next) => {
  const origin = c.req.header('Origin') ?? '';
  const allowed = (c.env.ALLOWED_ORIGINS ?? '').split(',').map((s) => s.trim());
  const isDev   = c.env.ENVIRONMENT !== 'production';

  const allow = isDev || allowed.includes(origin) || allowed.includes('*');

  if (allow) {
    c.header('Access-Control-Allow-Origin', origin || '*');
    c.header('Access-Control-Allow-Methods', 'GET, POST, PUT, PATCH, DELETE, OPTIONS');
    c.header('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-API-Key, X-Session-ID');
    c.header('Access-Control-Expose-Headers', 'X-RateLimit-Limit, X-RateLimit-Remaining, X-RateLimit-Reset');
    c.header('Access-Control-Max-Age', '86400');
  }

  if (c.req.method === 'OPTIONS') {
    return new Response(null, { status: 204 });
  }
  return next();
});

// ── Security headers ──────────────────────────────────────────────
app.use('*', async (c, next) => {
  await next();
  c.header('X-Content-Type-Options', 'nosniff');
  c.header('X-Frame-Options', 'DENY');
  c.header('Referrer-Policy', 'strict-origin-when-cross-origin');
});

// ── Rate limiting (skip admin + webhook routes) ───────────────────
app.use('/api/*', async (c, next) => {
  const path = c.req.path;
  if (
    path.startsWith('/api/admin') ||
    path.startsWith('/api/webhooks') ||
    path.startsWith('/api/summaries')
  ) {
    return next();
  }
  return rateLimitMiddleware(c as any, next);
});

// ── Health check ──────────────────────────────────────────────────
app.get('/health', (c) =>
  Response.json({
    status: 'ok',
    service: 'kissan-api',
    version: '1.0.0',
    env: c.env.ENVIRONMENT,
    ts: new Date().toISOString(),
  })
);

// ── Routes ────────────────────────────────────────────────────────
app.route('/api/catalog',          catalogRouter);    // GET, POST, PUT, DELETE /api/catalog[/:id]
app.route('/api',                  ordersRouter);     // POST /api/order
app.route('/api',                  otpRouter);        // POST /api/order/verify, /api/order/resend-otp
app.route('/api/webhooks',         paymentsRouter);   // POST /api/webhooks/razorpay
app.route('/api/admin',            adminRouter);      // /api/admin/*
app.route('/api/track',            trackRouter);      // GET /api/track/:ref
app.route('/api/summaries',        summariesRouter);  // /api/summaries/*

// ── Global error handler ─────────────────────────────────────────
app.onError((err, c) => {
  console.error('[Unhandled Error]', err);
  return Response.json(
    { success: false, error: 'Internal server error' },
    { status: 500 }
  );
});

// ── 404 ──────────────────────────────────────────────────────────
app.notFound((c) =>
  Response.json(
    { success: false, error: 'Route not found', path: c.req.path },
    { status: 404 }
  )
);

export default app;
