import { emailShell, deliveryBadge } from './base';
import type { DeliveryType } from '../types';

interface RejectionEmailOptions {
  customerName: string;
  orderRef: string;
  deliveryType: DeliveryType;
  reason: string;
  shopUrl: string;
}

export function rejectionEmail(opts: RejectionEmailOptions): { subject: string; html: string } {
  const html = emailShell(`
    <div class="card">
      <div class="card-header">
        <p style="margin:0 0 8px;">${deliveryBadge(opts.deliveryType)}</p>
        <p style="margin:0 0 8px;"><span class="badge badge-red">❌ Order Rejected</span></p>
        <h1>We're Sorry</h1>
        <p>
          Hi ${escHtml(opts.customerName)}, unfortunately your Kissan Connect order
          <strong style="color:#9d93f0;">${escHtml(opts.orderRef)}</strong> could not be fulfilled at this time.
        </p>
      </div>
      <div class="card-body">
        <div style="background:#180a0a;border:1px solid rgba(248,113,113,.2);border-left:3px solid #f87171;border-radius:8px;padding:16px;margin:0 0 20px;">
          <p style="margin:0 0 4px;font-size:12px;font-weight:700;text-transform:uppercase;color:#f87171;">Reason</p>
          <p style="margin:0;font-size:15px;color:#fca5a5;">${escHtml(opts.reason)}</p>
        </div>

        <p style="color:#b8b4d4;">
          This could be due to stock running out at the last moment, delivery not being possible to
          your area, or the farmer being unavailable. We apologise for the inconvenience.
        </p>

        <p style="color:#b8b4d4;">
          Any payment already made will be refunded within <strong style="color:#34d399;">5–7 business days</strong>
          to your original payment method.
        </p>

        <div style="text-align:center;margin:24px 0 8px;">
          <a href="${opts.shopUrl}" class="btn">🌿 Browse Other Products</a>
        </div>
      </div>
      <div class="card-footer">
        <p style="margin:0;font-size:13px;color:#5a5778;">
          Need help? <a href="mailto:support@kissanconnect.in">support@kissanconnect.in</a>
        </p>
      </div>
    </div>`,
    `Your order ${opts.orderRef} was rejected — see details`
  );

  return {
    subject: `❌ Order ${opts.orderRef} Rejected — Kissan Connect`,
    html,
  };
}

function escHtml(str: string): string {
  return str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
